package com.iare.club.service;
import com.fasterxml.jackson.databind.*;import com.iare.club.entity.MerchantPaymentConfig;import java.math.BigDecimal;import java.time.Duration;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.*;
@Component public class YoupiGatewayClient{
 private final RestClient http;private final String baseUrl;private final String merchantId;private final String merchantKey;private final String adminToken;private final boolean enabled;
 public YoupiGatewayClient(RestClient.Builder builder,@Value("${payments.youpi.base-url:http://localhost:6100}")String base,@Value("${payments.youpi.merchant-id:}")String id,@Value("${payments.youpi.merchant-key:}")String key,@Value("${payments.youpi.admin-token:}")String admin,@Value("${payments.youpi.integration-enabled:false}")boolean enabled){baseUrl=base.replaceAll("/$","");merchantId=id.strip();merchantKey=key.strip();adminToken=admin.strip();this.enabled=enabled;http=builder.baseUrl(baseUrl).build();}
 public Checkout createPayment(String orderId,BigDecimal amount,String returnUrl){requireMerchant();try{JsonNode n=http.post().uri("/api/v1/payments").header("X-Merchant-Id",merchantId).header("X-Merchant-Key",merchantKey).header("Idempotency-Key",orderId).contentType(MediaType.APPLICATION_JSON).body(Map.of("orderId",orderId,"amount",amount.setScale(2).toPlainString(),"currency","INR","method","UPI","returnUrl",returnUrl,"metadata",Map.of("source","FundRise","reference",orderId))).retrieve().body(JsonNode.class);if(n==null)throw new DepositService.FinancialException("YouPI-PG returned an empty response");return new Checkout(text(n,"paymentId"),text(n,"checkoutUrl"),text(n,"status"));}catch(RestClientResponseException e){throw new DepositService.FinancialException("YouPI-PG rejected payment creation: "+safeMessage(e));}catch(ResourceAccessException e){throw new DepositService.FinancialException("YouPI-PG payment service is unavailable");}}
 public void updateUpiSettings(MerchantPaymentConfig config){if(!enabled)return;if(adminToken.isBlank())throw new DepositService.FinancialException("YOUPI_ADMIN_TOKEN is required to update Payment Settings");try{http.post().uri("/api/v1/admin/upi-settings").header(HttpHeaders.AUTHORIZATION,"Bearer "+adminToken).header("X-Merchant-Id",merchantId).contentType(MediaType.APPLICATION_JSON).body(Map.of("merchantId",merchantId,"upiId",config.getUpiId(),"payeeName",config.getMerchantName(),"isMerchantEnabled",config.isActive())).retrieve().toBodilessEntity();}catch(RestClientResponseException e){throw new DepositService.FinancialException("YouPI-PG rejected UPI settings: "+safeMessage(e));}catch(ResourceAccessException e){throw new DepositService.FinancialException("YouPI-PG service is unavailable; settings were not changed");}}
 public ServiceStatus status(){if(!enabled)return new ServiceStatus(false,false,"Integration disabled");try{JsonNode n=http.get().uri("/health").retrieve().body(JsonNode.class);return new ServiceStatus(true,true,n==null?"UP":n.path("status").asText("UP"));}catch(RuntimeException e){return new ServiceStatus(true,false,"Unavailable");}}
 public boolean isEnabled(){return enabled;}private void requireMerchant(){if(!enabled)throw new DepositService.FinancialException("YouPI-PG integration is disabled");if(merchantId.isBlank()||merchantKey.isBlank())throw new DepositService.FinancialException("YouPI-PG merchant credentials are not configured");}
 private static String text(JsonNode n,String key){JsonNode value=n.get(key);if(value==null||value.asText().isBlank())throw new DepositService.FinancialException("YouPI-PG response missing "+key);return value.asText();}private static String safeMessage(RestClientResponseException e){String s=e.getResponseBodyAsString();return s==null||s.isBlank()?e.getStatusText():s.substring(0,Math.min(240,s.length()));}
 public record Checkout(String paymentId,String checkoutUrl,String status){}public record ServiceStatus(boolean configured,boolean available,String message){}
}
